macro.elementary.get_information_schema_.macro_sql:
{% macro get_information_schema_columns_materialized() %}
  {% if var("sync", false) %}
    {% do return("table") %}
  {% endif %}
  {% do return("view") %}
{% endmacro %}

{% macro get_information_schema_columns_query(is_model_build_context=true) %}
  {% if is_model_build_context %}
    {% set get_relation = ref %}
  {% else %}
    {% set get_relation = elementary.get_elementary_relation %}
  {% endif %}

  with dbt_models_data as (
      select
          database_name,
          schema_name,
          alias as table_name
      from {{ get_relation('dbt_models') }}
  ),

  dbt_snapshots_data as (
      select
          database_name,
          schema_name,
          alias as table_name
      from {{ get_relation('dbt_snapshots') }}
  ),

  dbt_sources_data as (
      select
          database_name,
          schema_name,
          name as table_name
      from {{ get_relation('dbt_sources') }}
  ),

  dbt_seeds_data as (
      select
          database_name,
          schema_name,
          name as table_name
      from {{ get_relation('dbt_seeds') }}
  ),

  tables_information as (
