model.encore_analytics.amazon_combined__.raw_code:
{{
    config(
        description='Margin Review — fee preview joined to SKU Master'
    )
}}

with fee_preview as (
    select * from {{ ref('stg_amazon_sp__fee_preview') }}
),

sku as (
    select * from {{ ref('dim_sku') }}
)

select
    fp.sku,
    sk.brand,
    sk.listing_name as model,
    sk.size_code,
    sk.segmentation,
    sk.seasonality,
    sk.discontinue_flag,
    fp.sales_price,
    fp.referral_fee,
    fp.fba_fee,
    sk.cogs,
    fp.sales_price - fp.referral_fee - fp.fba_fee - sk.cogs as pre_ppc_payout,
    div0(
        fp.sales_price - fp.referral_fee - fp.fba_fee - sk.cogs,
        fp.sales_price
    ) as pre_ppc_margin
from fee_preview fp
inner join sku sk on fp.sku = sk.sku
